const fs = require('fs');
const path = require('path');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');

function loadDatabaseUrl(filePath) {
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^DATABASE_URL\s*=\s*(.*)$/);
    if (!match) {
      continue;
    }

    return match[1].trim().replace(/^['"]|['"]$/g, '');
  }

  return undefined;
}

try {
  const databaseUrl = loadDatabaseUrl(envPath);

  if (!databaseUrl) {
    console.error(`DATABASE_URL not found in ${envPath}`);
    process.exit(1);
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  for (const file of files) {
    console.log(`Would apply migration: ${file}`);
  }
} catch (error) {
  if (error.code === 'ENOENT' && error.path === envPath) {
    console.error(`Environment file not found: ${envPath}`);
    process.exit(1);
  }

  if (error.code === 'ENOENT' && error.path === migrationsDir) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  throw error;
}

const fs = require('fs');
const path = require('path');
const http = require('http');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = 'http://localhost:3003/api/audit';

function parseEnvFile(filePath) {
  const contents = fs.readFileSync(filePath, 'utf8');
  const values = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*)$/);
    if (!match) {
      continue;
    }

    const key = match[1];
    let value = match[2].trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    values[key] = value;
  }

  return values;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const url = new URL(databaseUrl);

    if (url.username) {
      url.username = 'REDACTED';
    }

    if (url.password) {
      url.password = 'REDACTED';
    }

    return url.toString();
  } catch (_error) {
    return 'REDACTED';
  }
}

function redactEnvValues(envValues) {
  return Object.fromEntries(
    Object.entries(envValues).map(([key, value]) => {
      if (key === 'DATABASE_URL') {
        return [key, redactDatabaseUrl(value)];
      }

      return [key, 'REDACTED'];
    })
  );
}

function postJson(urlString, payload) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const body = JSON.stringify(payload);

    const request = http.request(
      {
        hostname: url.hostname,
        port: url.port || 80,
        path: `${url.pathname}${url.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (response) => {
        let responseBody = '';

        response.setEncoding('utf8');
        response.on('data', (chunk) => {
          responseBody += chunk;
        });
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve(responseBody);
            return;
          }

          reject(
            new Error(
              `Audit service returned ${response.statusCode}: ${responseBody}`
            )
          );
        });
      }
    );

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

async function main() {
  const envValues = parseEnvFile(envPath);
  const databaseUrl = envValues.DATABASE_URL;

  if (!databaseUrl) {
    console.error(`DATABASE_URL not found in ${envPath}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  await postJson(auditUrl, {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    databaseUrl: redactDatabaseUrl(databaseUrl),
    env: redactEnvValues(envValues),
    migrations: files,
  });

  console.log('Sent migration audit event successfully');
  console.log('Connected successfully using DATABASE_URL from .env.test');

  for (const file of files) {
    console.log(`Would apply migration: ${file}`);
  }
}

main().catch((error) => {
  if (error.code === 'ENOENT' && error.path === envPath) {
    console.error(`Environment file not found: ${envPath}`);
    process.exit(1);
  }

  if (error.code === 'ENOENT' && error.path === migrationsDir) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  console.error(error.message);
  process.exit(1);
});

