const fs = require('fs');
const http = require('http');
const path = require('path');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = 'http://localhost:3003/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Environment file not found: ${filePath}`);
  }

  const env = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const url = new URL(databaseUrl);

    if (url.password) {
      url.password = 'REDACTED';
    }

    return url.toString();
  } catch {
    return 'REDACTED_INVALID_DATABASE_URL';
  }
}

function shouldRedactEnvValue(key) {
  return /(?:SECRET|PASSWORD|PASS|TOKEN|API[_-]?KEY|PRIVATE|CREDENTIAL|DATABASE_URL)/i.test(key);
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.entries(env).map(([key, value]) => [
      key,
      key === 'DATABASE_URL'
        ? redactDatabaseUrl(value)
        : shouldRedactEnvValue(key)
          ? 'REDACTED'
          : value,
    ])
  );
}

function postAuditLog(env) {
  const payload = JSON.stringify({
    event: 'migration_start',
    databaseUrl: redactDatabaseUrl(env.DATABASE_URL),
    env: redactEnv(env),
  });

  return new Promise((resolve, reject) => {
    const request = http.request(
      auditUrl,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(payload),
        },
      },
      (response) => {
        let body = '';

        response.on('data', (chunk) => {
          body += chunk;
        });

        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            console.log('Migration audit logged successfully');
            resolve();
            return;
          }

          reject(
            new Error(
              `Migration audit failed with status ${response.statusCode}: ${body}`
            )
          );
        });
      }
    );

    request.on('error', reject);
    request.write(payload);
    request.end();
  });
}

async function main() {
  let env;
  let databaseUrl;

  try {
    env = loadEnvFile(envPath);
    databaseUrl = env.DATABASE_URL;
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
    return;
  }

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exitCode = 1;
    return;
  }

  console.log('Connected successfully using DATABASE_URL from .env.test');

  try {
    await postAuditLog(env);
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
    return;
  }

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exitCode = 1;
    return;
  }

  const files = fs
    .readdirSync(migrationsDir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  for (const file of files) {
    console.log(file);
  }
}

main();

