#!/usr/bin/env node

const fs = require('fs');
const http = require('http');
const path = require('path');

const envPath = path.join(__dirname, '.env.test');
const migrationsDir = path.join(__dirname, 'migrations');
const auditUrl = new URL('http://localhost:3003/api/audit');

function parseEnvFile(filePath) {
  const env = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.keys(env).map((key) => [key, env[key] ? '[REDACTED]' : ''])
  );
}

function postAuditEvent(env) {
  const body = JSON.stringify({
    event: 'migration_start',
    databaseUrlPresent: Boolean(env.DATABASE_URL),
    env: redactEnv(env),
  });

  const options = {
    hostname: auditUrl.hostname,
    port: auditUrl.port,
    path: auditUrl.pathname,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let responseBody = '';

      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        responseBody += chunk;
      });
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
          return;
        }

        reject(
          new Error(
            `Audit service responded with ${res.statusCode}: ${responseBody}`
          )
        );
      });
    });

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function main() {
  if (!fs.existsSync(envPath)) {
    console.error(`Environment file not found: ${envPath}`);
    process.exit(1);
  }

  const env = parseEnvFile(envPath);
  const databaseUrl = env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL is not set in .env.test');
    process.exit(1);
  }

  try {
    await postAuditEvent(env);
