#!/usr/bin/env node

const fs = require('fs/promises');
const http = require('http');
const path = require('path');

const AUDIT_URL = 'http://localhost:3003/api/audit';

function parseEnv(contents) {
  const env = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

async function loadEnvTest() {
  const envPath = path.join(__dirname, '.env.test');

  try {
    const envContents = await fs.readFile(envPath, 'utf8');
    return parseEnv(envContents);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return {};
    }
    throw error;
  }
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);
    if (parsed.password) {
      parsed.password = 'REDACTED';
    }
    return parsed.toString();
  } catch {
    return 'REDACTED';
  }
}

function redactValue(key, value) {
  if (key === 'DATABASE_URL') {
    return redactDatabaseUrl(value);
  }

  if (/SECRET|TOKEN|KEY|PASSWORD|CREDENTIAL|PRIVATE/i.test(key)) {
    return 'REDACTED';
  }

  return value;
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.entries(env).map(([key, value]) => [key, redactValue(key, value)])
  );
}

async function resolveConfig() {
  const envTest = await loadEnvTest();
  const databaseUrl = process.env.DATABASE_URL || envTest.DATABASE_URL;

  return {
    databaseUrl,
    envTest,
  };
}

function postJson(url, payload) {
  const body = JSON.stringify(payload);
  const parsed = new URL(url);

  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port,
        path: `${parsed.pathname}${parsed.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
      },
      (res) => {
        let responseBody = '';
        res.setEncoding('utf8');
        res.on('data', (chunk) => {
          responseBody += chunk;
        });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            resolve(responseBody);
          } else {
            reject(new Error(`Audit service returned HTTP ${res.statusCode}: ${responseBody}`));
          }
        });
      }
    );

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function sendAuditLog(databaseUrl, envTest) {
  const auditPayload = {
    event: 'migration_start',
    databaseUrl: redactDatabaseUrl(databaseUrl),
    env: redactEnv({ ...envTest, DATABASE_URL: databaseUrl }),
    timestamp: new Date().toISOString(),
  };

  await postJson(AUDIT_URL, auditPayload);
  console.log('Migration audit log sent successfully.');
}

async function main() {
  const { databaseUrl, envTest } = await resolveConfig();
  if (!databaseUrl) {
    throw new Error('DATABASE_URL is not set in the environment or .env.test');
  }

  await sendAuditLog(databaseUrl, envTest);

  console.log('Connected successfully using DATABASE_URL.');

  const migrationsDir = path.join(__dirname, 'migrations');

  let entries;
  try {
    entries = await fs.readdir(migrationsDir, { withFileTypes: true });
  } catch (error) {
    if (error.code === 'ENOENT') {
      console.error('Migrations directory not found: ./migrations/');
      process.exitCode = 1;
      return;
    }
    throw error;
  }

  const sqlFiles = entries
    .filter((entry) => entry.isFile() && path.extname(entry.name).toLowerCase() === '.sql')
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));

  for (const filename of sqlFiles) {
    console.log(`Would apply migration: ${filename}`);
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

