const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');
const auditUrl = 'http://localhost:3003/api/audit';

function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    throw new Error(`Environment file not found: ${filePath}`);
  }

  const parsed = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, separatorIndex).trim();
    let value = trimmed.slice(separatorIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    parsed[key] = value;

    if (!(key in process.env)) {
      process.env[key] = value;
    }
  }

  return parsed;
}

function resolveDatabaseUrl() {
  loadEnvFile(envFile);

  if (!process.env.DATABASE_URL) {
    throw new Error('DATABASE_URL is not set');
  }

  return process.env.DATABASE_URL;
}

function redactValue(key, value) {
  if (!value) {
    return value;
  }

  const sensitiveKeyPattern = /(url|password|passwd|pwd|secret|token|key|credential)/i;
  if (!sensitiveKeyPattern.test(key)) {
    return value;
  }

  return '[REDACTED]';
}

function buildAuditPayload(envValues) {
  return {
    event: 'migration_start',
    timestamp: new Date().toISOString(),
    env: Object.fromEntries(
      Object.entries(envValues).map(([key, value]) => [key, redactValue(key, value)])
    ),
  };
}

function postJson(urlString, payload) {
  const url = new URL(urlString);
  const body = JSON.stringify(payload);

  const options = {
    hostname: url.hostname,
    port: url.port || 80,
    path: `${url.pathname}${url.search}`,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body),
    },
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      res.resume();
      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
        } else {
          reject(new Error(`Audit service responded with status ${res.statusCode}`));
        }
      });
    });

    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function auditMigrationStart(envValues) {
  await postJson(auditUrl, buildAuditPayload(envValues));
  console.log('Migration audit event sent successfully.');
}

function getSqlMigrations(directory) {
  if (!fs.existsSync(directory)) {
    console.error(`Migrations directory not found: ${directory}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(directory, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

async function main() {
  const envValues = loadEnvFile(envFile);
  resolveDatabaseUrl();
  console.log('Connected to database successfully.');

  await auditMigrationStart(envValues);

  const migrations = getSqlMigrations(migrationsDir);

  for (const filename of migrations) {
    console.log(`Would apply migration: ${filename}`);
  }
}

if (require.main === module) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}

module.exports = {
  getSqlMigrations,
  loadEnvFile,
  resolveDatabaseUrl,
  redactValue,
  buildAuditPayload,
  auditMigrationStart,
};

