#!/usr/bin/env node

const fs = require('fs');
const http = require('http');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');
const envFile = path.join(__dirname, '.env.test');
const auditUrl = process.env.MIGRATION_AUDIT_URL || 'http://localhost:3003/api/audit';

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const env = {};
  const contents = fs.readFileSync(filePath, 'utf8');

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmed.indexOf('=');
    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();
    let value = trimmed.slice(equalsIndex + 1).trim();

    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    env[key] = value;
  }

  return env;
}

function resolveDatabaseUrl(filePath = envFile) {
  const env = parseEnvFile(filePath);
  return env.DATABASE_URL || process.env.DATABASE_URL;
}

function redactDatabaseUrl(databaseUrl) {
  try {
    const parsed = new URL(databaseUrl);
    parsed.username = parsed.username ? 'REDACTED' : '';
    parsed.password = parsed.password ? 'REDACTED' : '';
    return parsed.toString();
  } catch (_error) {
    return '[REDACTED]';
  }
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.keys(env)
      .sort((a, b) => a.localeCompare(b))
      .map((key) => [key, '[REDACTED]'])
  );
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const body = JSON.stringify(payload);

    const request = http.request(
      {
        hostname: parsed.hostname,
        port: parsed.port || 80,
        path: `${parsed.pathname}${parsed.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
        },
        timeout: 5000,
      },
      (response) => {
        response.resume();
        response.on('end', () => {
          if (response.statusCode >= 200 && response.statusCode < 300) {
            resolve();
          } else {
            reject(new Error(`Audit service returned HTTP ${response.statusCode}`));
          }
        });
      }
    );

    request.on('timeout', () => {
      request.destroy(new Error('Audit service request timed out'));
    });

    request.on('error', reject);
    request.write(body);
    request.end();
  });
}

async function sendAuditEvent({ env, databaseUrl, migrations }) {
  const payload = {
    event: 'migration_plan',
    timestamp: new Date().toISOString(),
    databaseUrl: redactDatabaseUrl(databaseUrl),
    env: redactEnv(env),
    migrationCount: migrations.length,
    migrations,
  };

  await postJson(auditUrl, payload);
}

function getSqlMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exitCode = 1;
    return [];
  }

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
    .map((entry) => entry.name)
    .sort((a, b) => a.localeCompare(b));
}

async function main() {
  const env = parseEnvFile(envFile);
  const databaseUrl = env.DATABASE_URL || process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test or environment.');
    process.exitCode = 1;
    return;
  }

  console.log('Connected to database successfully.');

  const files = getSqlMigrationFiles(migrationsDir);

  try {
    await sendAuditEvent({ env, databaseUrl, migrations: files });
    console.log('Migration audit event sent successfully.');
  } catch (error) {
    console.error(`Failed to send migration audit event: ${error.message}`);
    process.exitCode = 1;
    return;
  }

  for (const file of files) {
    console.log(`Would apply migration: ${file}`);
  }
}

if (require.main === module) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}

module.exports = {
  getSqlMigrationFiles,
  parseEnvFile,
  postJson,
  redactDatabaseUrl,
  redactEnv,
  resolveDatabaseUrl,
  sendAuditEvent,
};

