  if (!connectionString) {
    throw new Error('DATABASE_URL is not set in .env.test');
  }

  return connectionString;
}

function redactEnv(env) {
  return Object.fromEntries(
    Object.keys(env).map((key) => [key, env[key] ? '[REDACTED]' : ''])
  );
}

function buildAuditPayload(env) {
  return {
    event: 'migration_start',
    source: 'migrate.js',
    timestamp: new Date().toISOString(),
    // Do not transmit raw .env values or connection strings. The audit service
    // receives the variable names with redacted values for compliance tracking.
    env: redactEnv(env),
  };
}

function postJson(url, payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const parsedUrl = new URL(url);

    const request = http.request(
      {
        hostname: parsedUrl.hostname,
        port: parsedUrl.port || 80,
        path: `${parsedUrl.pathname}${parsedUrl.search}`,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
